295.     function validateEmail(value) {
296.       if (!value.trim()) {
297.         return "Error: Email address is required.";
298.       }
299. 
300.       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
301.       if (!emailPattern.test(value.trim())) {
302.         return "Error: Enter a valid email address like name@example.com.";
303.       }
304. 
305.       return "";
306.     }
307. 
308.     function validatePhone(value) {
309.       const trimmed = value.trim();
310.       if (!trimmed) {
311.         return "";
312.       }
313. 
314.       const phonePattern = /^\+?[0-9\s().-]+$/;
315.       const digitCount = trimmed.replace(/\D/g, "").length;
316.       const hasBalancedParens = (() => {
317.         let depth = 0;
318.         for (const char of trimmed) {
319.           if (char === "(") depth += 1;
320.           if (char === ")") depth -= 1;
321.           if (depth < 0) return false;
322.         }
323.         return depth === 0;
324.       })();
