 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content"></main>

   <script>
     const state = {
       values: {
         fullName: "",
         email: "",
         phone: ""
       },
       touched: {
         fullName: false,
         email: false,
         phone: false
       },
       submitted: false,
       status: "",
       focusFirstInvalid: false
     };

     const app = document.getElementById("main-content");

     function escapeHtml(value) {
       return String(value)
         .replaceAll("&", "&amp;")
         .replaceAll("<", "&lt;")
         .replaceAll(">", "&gt;")
         .replaceAll('"', "&quot;")
         .replaceAll("'", "&#39;");
     }

     function validateFullName(value) {
       if (!value.trim()) {
         return "Error: Full name is required.";
       }
       return "";
     }

     function validateEmail(value) {
       if (!value.trim()) {
         return "Error: Email address is required.";
       }

       const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
       if (!emailPattern.test(value.trim())) {
         return "Error: Enter a valid email address like name@example.com.";
       }

       return "";
     }

     function validatePhone(value) {
       const trimmed = value.trim();
       if (!trimmed) {
         return "";
       }

       const phonePattern = /^\+?[0-9\s().-]+$/;
       const digitCount = trimmed.replace(/\D/g, "").length;
       const hasBalancedParens = (() => {
         let depth = 0;
         for (const char of trimmed) {
           if (char === "(") depth += 1;
           if (char === ")") depth -= 1;
           if (depth < 0) return false;
         }
         return depth === 0;
       })();

       if (!phonePattern.test(trimmed) || !hasBalancedParens || digitCount < 7) {
         return "Error: Enter a phone number in a format like +1 555 123 4567.";
       }

       return "";
     }

     function isFieldActive(name) {
       return state.submitted || state.touched[name];
     }

     function getFieldError(name) {
       switch (name) {
         case "fullName":
           return validateFullName(state.values.fullName);
         case "email":
           return validateEmail(state.values.email);
         case "phone":
           return validatePhone(state.values.phone);
         default:
           return "";
       }
     }

     function renderField({
       id,
       label,
       type = "text",
       autocomplete,
       value,
       helperText = "",
       required = false,
       inputMode = "",
       placeholder = ""
     }) {
       const error = getFieldError(id);
       const showError = Boolean(error) && isFieldActive(id);
       const helperId = helperText ? `${id}-hint` : "";
       const errorId = `${id}-error`;
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");

       return `
         <div class="form-field ${id === "phone" ? "form-field--full" : ""}">
           <label for="${id}">
             ${escapeHtml(label)}
             ${required ? '<span class="required-marker" aria-hidden="true">*</span>' : ''}
           </label>
           <input
             id="${id}"
             name="${id}"
             type="${type}"
             ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
             ${inputMode ? `inputmode="${inputMode}"` : ""}
             ${placeholder ? `placeholder="${escapeHtml(placeholder)}"` : ""}
             value="${escapeHtml(value)}"
             ${required ? "required" : ""}
             ${required ? 'aria-required="true"' : ""}
             ${showError ? 'aria-invalid="true"' : ""}
             ${describedBy ? `aria-describedby="${describedBy}"` : ""}
           >
           ${helperText ? `<p class="field-hint" id="${helperId}">${escapeHtml(helperText)}</p>` : ""}
           <p class="field-error" id="${errorId}" role="alert" aria-live="polite" aria-atomic="true" data-empty="${showError ? "false" : "true"}">${showError ? escapeHtml(error) : ""}</p>
         </div>
       `;
     }

     function render() {
       const fieldNames = ["fullName", "email", "phone"];
       const visibleErrors = fieldNames
         .map((name) => ({ name, error: getFieldError(name) }))
         .filter(({ name, error }) => Boolean(error) && isFieldActive(name));
       const statusText = state.submitted
         ? (visibleErrors.length
           ? `Please fix ${visibleErrors.length} field${visibleErrors.length === 1 ? "" : "s"} above.`
           : "Ready to send.")
         : "";

       app.innerHTML = `
         <section class="hero" aria-labelledby="page-title">
           <p class="eyebrow">Support</p>
           <h1 id="page-title">Contact the support team</h1>
           <p class="intro">Send us your contact details and we’ll use them to follow up about your support request.</p>
         </section>

         <section class="form-card" aria-labelledby="contact-form-title">
           <h2 id="contact-form-title" class="sr-only">Contact form</h2>
           <form id="contact-form" novalidate>
             <div class="form-grid">
               ${renderField({
                 id: "fullName",
                 label: "Full name",
                 value: state.values.fullName,
                 autocomplete: "name",
                 required: true,
                 placeholder: "Jordan Lee"
               })}
               ${renderField({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 value: state.values.email,
                 autocomplete: "email",
                 required: true,
                 placeholder: "jordan@example.com"
               })}
               ${renderField({
                 id: "phone",
                 label: "Phone number (optional)",
                 type: "tel",
                 value: state.values.phone,
                 autocomplete: "tel",
                 inputMode: "tel",
                 helperText: "Use a format like +1 555 123 4567, (555) 123-4567, or 555-123-4567."
               })}
             </div>

             <div class="form-actions">
               <button type="submit" class="submit-button">Send message</button>
               <p class="status" role="status" aria-live="polite" aria-atomic="true" data-empty="${statusText ? "false" : "true"}">${escapeHtml(statusText)}</p>
             </div>
           </form>
         </section>
       `;

       const firstInvalid = state.focusFirstInvalid ? app.querySelector('[aria-invalid="true"]') : null;
       state.focusFirstInvalid = false;
       if (firstInvalid) {
         firstInvalid.focus();
       }
     }

     app.addEventListener("input", (event) => {
       const target = event.target;
       if (!(target instanceof HTMLInputElement)) {
         return;
       }

       if (!(target.name in state.values)) {
         return;
       }

       state.values[target.name] = target.value;
       state.status = "";
       render();
     });

     app.addEventListener("blur", (event) => {
       const target = event.target;
       if (!(target instanceof HTMLInputElement)) {
         return;
       }

       if (!(target.name in state.touched)) {
         return;
       }

       state.touched[target.name] = true;
       render();
     }, true);

     app.addEventListener("submit", (event) => {
       event.preventDefault();
       state.submitted = true;
       state.touched.fullName = true;
       state.touched.email = true;
       state.touched.phone = true;

       const fullNameError = validateFullName(state.values.fullName);
       const emailError = validateEmail(state.values.email);
       const phoneError = validatePhone(state.values.phone);
       const errors = [fullNameError, emailError, phoneError].filter(Boolean);

       state.status = errors.length
         ? `Please fix ${errors.length} field${errors.length === 1 ? "" : "s"} above.`
         : "Ready to send.";
       state.focusFirstInvalid = Boolean(errors.length);

       render();
     });

     render();
   </script>
')

